import{_ as t,o as h,c as i,a3 as a}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Quản trị viên (Admin)","description":"","frontmatter":{},"headers":[],"relativePath":"vai-tro/admin.md","filePath":"vai-tro/admin.md","lastUpdated":1781595364000}'),c={name:"vai-tro/admin.md"};function o(g,n,l,e,r,u){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="quan-tri-vien-admin" tabindex="-1">Quản trị viên (Admin) <a class="header-anchor" href="#quan-tri-vien-admin" aria-label="Permalink to &quot;Quản trị viên (Admin)&quot;">​</a></h1><p>Trang <strong>lối đi nhanh</strong> cho vai trò <strong>Admin</strong> (<code>admin</code>) — quản trị gần như toàn bộ hệ thống trong phạm vi công ty được gán. Khác biệt chính so với Super Admin: <strong>không có quyền Xóa</strong> ở phần lớn module, và <strong>Cài đặt</strong> chỉ <code>Xem</code>.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Mã vai trò:</strong> <code>admin</code>.</li><li><strong>Phạm vi dữ liệu:</strong> theo <strong>công ty được gán</strong>.</li><li><strong>Quyền mặc định:</strong> mọi hành động <strong>trừ <code>Xóa</code></strong>; riêng <strong>Cài đặt</strong> chỉ <code>Xem</code>.</li></ul></div><h2 id="ban-thay-nhung-gi" tabindex="-1">Bạn thấy những gì? <a class="header-anchor" href="#ban-thay-nhung-gi" aria-label="Permalink to &quot;Bạn thấy những gì?&quot;">​</a></h2><p>Admin thấy hầu hết module trong cả 3 nhóm điều hướng:</p><ul><li><strong>Điều Hướng:</strong> Bảng điều khiển, Quản lý Tài sản, Tổ chức.</li><li><strong>Hoạt Động:</strong> Ticket, Công việc, Đặt phòng, Yêu cầu tuyển dụng, Chấm công, Thông báo, Lịch sử.</li><li><strong>Quản Trị:</strong> Quản lý Hồ sơ (Nhân sự), Nguồn Nhân Lực, Biểu mẫu, Người dùng, Cài đặt.</li></ul><div class="warning custom-block"><p class="custom-block-title">Admin không xóa được</p><p>Mặc định Admin <strong>không có quyền <code>Xóa</code></strong>. Việc xóa tài sản đi qua <strong>luồng duyệt</strong> (<a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu xóa</a>); xóa người dùng/tổ chức cần Super Admin. <strong>Cấu hình Ticket</strong> cũng chỉ Super Admin mới vào được.</p></div><h2 id="cong-viec-thuong-ngay" tabindex="-1">Công việc thường ngày <a class="header-anchor" href="#cong-viec-thuong-ngay" aria-label="Permalink to &quot;Công việc thường ngày&quot;">​</a></h2><ul><li>[ ] Tạo/sửa người dùng, gán vai trò &amp; phân quyền chi tiết → <a href="/help/quan-tri/nguoi-dung.html">Người dùng &amp; phân quyền</a></li><li>[ ] Quản lý tài sản (phần cứng, phần mềm, domain, email) → <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a></li><li>[ ] Quản lý cơ cấu tổ chức (công ty, phòng ban, bộ phận) → <a href="/help/quan-tri/co-cau-to-chuc.html">Cơ cấu tổ chức</a></li><li>[ ] Xử lý ticket, công việc, đặt phòng → <a href="/help/chuc-nang/tickets.html">Ticket Hỗ trợ</a> · <a href="/help/chuc-nang/cong-viec.html">Công việc</a></li><li>[ ] Quản lý hồ sơ nhân sự, hợp đồng → <a href="/help/chuc-nang/nhan-su.html">Quản lý Hồ sơ (Nhân sự)</a></li><li>[ ] Tuyển dụng, onboarding, kho CV/JD → <a href="/help/chuc-nang/nguon-nhan-luc.html">Nguồn nhân lực (ATS)</a></li><li>[ ] Đăng thông báo nội bộ → <a href="/help/chuc-nang/dashboard.html">Thông báo (Truyền thông)</a></li><li>[ ] Cấu hình máy chấm công &amp; loại phép → <a href="/help/quan-tri/cau-hinh-cham-cong.html">Cấu hình Chấm công</a></li><li>[ ] Theo dõi lịch sử hoạt động → <a href="/help/chuc-nang/lich-su.html">Lịch sử</a></li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Màn hình quản trị của vai trò Admin. <em>(Ảnh sẽ được bổ sung.)</em></p></div><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a> · <a href="/help/vai-tro/super-admin.html">Super Admin</a></p>',12)])])}const d=t(c,[["render",o]]);export{m as __pageData,d as default};
